import{_ as a,o as t,c as i,a5 as s}from"./chunks/framework.CnBNXlt7.js";const k=JSON.parse('{"title":"日本的行政区划","description":"","frontmatter":{},"headers":[],"relativePath":"random-notes/divisions-jp.md","filePath":"random-notes/divisions-jp.md","lastUpdated":1752665399000}'),r={name:"random-notes/divisions-jp.md"};function n(g,o,l,p,e,u){return t(),i("div",null,[...o[0]||(o[0]=[s('<h1 id="日本的行政区划" tabindex="-1">日本的行政区划 <a class="header-anchor" href="#日本的行政区划" aria-label="Permalink to &quot;日本的行政区划&quot;">​</a></h1><p>日本的行政区划划分清晰，主要可以分为两级。</p><ol><li><p><strong>一级行政区划</strong>：</p><ul><li>都（と）：全国共有1个都，即东京都（とうきょうと）。</li><li>道（どう）：全国共有1个道，即北海道（ほっかいどう）。</li><li>府（ふ）：全国共有2个府，分别是大阪府（おおさかふ）和京都府（きょうとふ）。</li><li>県（けん）：全国共有43个县，如青森县（あおもりけん）、秋田县（あきたけん）等。</li></ul></li><li><p><strong>二级行政区划</strong>：</p><ul><li>市（し）：日本的市是比町规模大的城镇，但下不设区，也不设综合性的派出机构，只根据单项工作需要设若干个事务所、窗口等。设市有四项条件，包括人口在5万以上、中心市区的居住户数占全市总户数的60%以上等。</li><li>町（ちょう）：町的设置条件由都道府县自行规定，如东京都规定町的构成条件包括人口在1.8万以上等。町比村具有更多的城市特点，相当于我国的镇。</li><li>村（そん）：日本的村相当于我国的乡，有浓郁的农村和农业特点。</li></ul></li><li><p><strong>其他行政区划</strong>：</p><ul><li>特别区（とくべつく）：在政令指定都市下设有的特别区，如东京都的港区、新宿区等。</li><li>支厅（しちょう）：部分地区设立的行政机构，作为都道府县的派出机关。</li><li>郡（ぐん）：虚级行政区划，现在已较少使用。</li></ul></li></ol><p>日本全国共划分为47个一级行政区，即1都、1道、2府和43个县。这些行政区划都实行地方自治，即按照居民意愿，根据民主原则，实施地方的政治和行政。都道府县是包括市町村的广域地方公共团体，是市町村的上级机关。市、町、村则是基层行政组织。</p><div class="info custom-block"><p class="custom-block-title">一共10个地区，一级行政区划如下</p><p><strong>北海道</strong><br><strong>Hokkaido</strong></p><p><strong>東北</strong> 青森 秋田 岩手 山形 宮城 福島<br><strong>Tohoku</strong> Aomori Akita Iwate Yamagata Miyagi Fukushima</p><p><strong>北陸信越</strong> 新潟 富山 石川 福井 長野<br><strong>Hokuriku Shinetsu</strong> Niigata Toyama Ishikawa Fukui Nagano</p><p><strong>関東</strong> 東京 神奈川 千葉 埼玉 茨城 栃木 群馬<br><strong>Kanto</strong> Tokyo Kanagawa Chiba Saitama Ibaraki Tochigi Gunma</p><p><strong>東海</strong> 山梨 静岡 岐阜 愛知 三重<br><strong>Tokai</strong> Yamanashi Shizuoka Gifu Aichi Mie</p><p><strong>関西</strong> 京都 大阪 滋賀 兵庫 奈良 和歌山<br><strong>Kansai</strong> Kyoto Osaka Shiga Hyogo Nara Wakayama</p><p><strong>中国</strong> 鳥取 島根 岡山 広島 山口<br><strong>Chugoku</strong> Tottori Shimane Okayama Hiroshima Yamaguchi</p><p><strong>四国</strong> 徳島 香川 愛媛 高知<br><strong>Shikoku</strong> Tokushima Kagawa Ehime Kochi</p><p><strong>九州</strong> 福岡 佐賀 長崎 大分 熊本 宮崎 鹿児島<br><strong>Kyushu</strong> Fukuoka Saga Nagasaki Oita Kumamoto Miyazaki Kagoshima</p><p><strong>沖縄</strong><br><strong>Okinawa</strong></p></div>',5)])])}const h=a(r,[["render",n]]);export{k as __pageData,h as default};
